import React, { useEffect, useState } from 'react';
import { Alert, Box, Button, Card, CardContent, Chip, CircularProgress, Container, Stack, TextField, Typography } from '@mui/material';
import { useNavigate, useParams } from 'react-router-dom';
import api from '../../services/api';

export default function PublicCarbonPassportPage() {
  const { token } = useParams<{ token: string }>();
  const navigate = useNavigate();
  const [lookup, setLookup] = useState('');
  const [data, setData] = useState<Record<string, unknown> | null>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(Boolean(token));

  useEffect(() => {
    if (!token) {
      setLoading(false);
      setData(null);
      setError('');
      return;
    }
    setLoading(true);
    api.getPublicCarbonPassport(token).then((res) => {
      if (res.success) setData(res.data as Record<string, unknown>);
      else setError(res.message || 'Passport not found');
    }).catch(() => setError('Passport not found'))
      .finally(() => setLoading(false));
  }, [token]);

  if (!token) {
    return (
      <Container maxWidth="sm" sx={{ py: 4 }}>
        <Card>
          <CardContent>
            <Typography variant="h5" gutterBottom>Verified Carbon Passport</Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Paste the passport link token from your supplier to open a public footprint.
            </Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
              <TextField
                fullWidth
                size="small"
                label="Passport token"
                value={lookup}
                onChange={(event) => setLookup(event.target.value)}
              />
              <Button
                variant="contained"
                disabled={!lookup.trim()}
                onClick={() => navigate(`/carbon-passport/${encodeURIComponent(lookup.trim())}`)}
              >
                Look up
              </Button>
            </Stack>
          </CardContent>
        </Card>
      </Container>
    );
  }

  if (loading && !data && !error) {
    return (
      <Box display="flex" justifyContent="center" py={8}>
        <CircularProgress />
      </Box>
    );
  }

  const supplier = (data?.supplier || {}) as Record<string, string>;
  const footprint = (data?.footprint || {}) as Record<string, number>;

  return (
    <Container maxWidth="sm" sx={{ py: 4 }}>
      <Card>
        <CardContent>
          <Typography variant="h5" gutterBottom>
            Verified Carbon Passport
          </Typography>
          {error && <Alert severity="error">{error}</Alert>}
          {data && (
            <>
              <Typography variant="h6">{supplier.companyName}</Typography>
              <Chip
                label={supplier.verificationStatus === 'verified' ? 'Verified supplier' : 'Pending verification'}
                color={supplier.verificationStatus === 'verified' ? 'success' : 'warning'}
                sx={{ my: 1 }}
              />
              <Typography variant="body2" color="text.secondary">
                {footprint.totalEmissionsKgCo2e?.toLocaleString('en-IN')} kg CO₂e total · Score {footprint.carbonScore ?? '—'}
              </Typography>
              <Typography variant="body2" sx={{ mt: 1 }}>
                Scope 1: {footprint.scope1KgCo2e ?? 0} kg · Scope 2: {footprint.scope2KgCo2e ?? 0} kg · Scope 3:{' '}
                {footprint.scope3KgCo2e ?? 0} kg
              </Typography>
            </>
          )}
        </CardContent>
      </Card>
    </Container>
  );
}
